create extension if not exists pgcrypto;
create type public.server_role as enum ('owner','admin','moderator','member');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'User',avatar_url text,created_at timestamptz not null default now());
create table public.servers(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 1 and 60),owner_id uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table public.server_members(server_id uuid references public.servers(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,role public.server_role not null default 'member',joined_at timestamptz not null default now(),primary key(server_id,user_id));
create table public.channels(id uuid primary key default gen_random_uuid(),server_id uuid not null references public.servers(id) on delete cascade,name text not null,topic text not null default '',position int not null default 0,created_at timestamptz not null default now(),unique(server_id,name));
create table public.messages(id uuid primary key default gen_random_uuid(),channel_id uuid not null references public.channels(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,content text not null check(char_length(content)<=4000),reply_to uuid references public.messages(id) on delete set null,created_at timestamptz not null default now());
create table public.message_reactions(message_id uuid references public.messages(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,emoji text not null,created_at timestamptz not null default now(),primary key(message_id,user_id,emoji));
create table public.friendships(requester_id uuid references public.profiles(id) on delete cascade,addressee_id uuid references public.profiles(id) on delete cascade,status text not null default 'pending' check(status in('pending','accepted','blocked')),created_at timestamptz not null default now(),primary key(requester_id,addressee_id),check(requester_id<>addressee_id));
create table public.dm_conversations(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now());
create table public.dm_participants(conversation_id uuid references public.dm_conversations(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,primary key(conversation_id,user_id));
create table public.dm_messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.dm_conversations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,content text not null check(char_length(content) between 1 and 4000),created_at timestamptz not null default now());
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),split_part(new.email,'@',1),'User')); return new; end $$;
create trigger auth_user_profile after insert on auth.users for each row execute procedure public.new_profile();
create or replace function public.owner_membership() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.server_members(server_id,user_id,role) values(new.id,new.owner_id,'owner'); return new; end $$;
create trigger server_owner after insert on public.servers for each row execute procedure public.owner_membership();
create or replace function public.is_member(sid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.server_members where server_id=sid and user_id=(select auth.uid())) $$;
create or replace function public.channel_member(cid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.channels c join public.server_members sm on sm.server_id=c.server_id where c.id=cid and sm.user_id=(select auth.uid())) $$;
alter table public.profiles enable row level security; alter table public.servers enable row level security; alter table public.server_members enable row level security; alter table public.channels enable row level security; alter table public.messages enable row level security; alter table public.message_reactions enable row level security; alter table public.friendships enable row level security; alter table public.dm_conversations enable row level security; alter table public.dm_participants enable row level security; alter table public.dm_messages enable row level security;
create policy "profiles read" on public.profiles for select to authenticated using(true);
create policy "profile self update" on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy "read joined servers" on public.servers for select to authenticated using(public.is_member(id));
create policy "create server owner" on public.servers for insert to authenticated with check(owner_id=(select auth.uid()));
create policy "update own server" on public.servers for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy "delete own server" on public.servers for delete to authenticated using(owner_id=(select auth.uid()));
create policy "members list" on public.server_members for select to authenticated using(public.is_member(server_id));
create policy "membership insert starter" on public.server_members for insert to authenticated with check(user_id=(select auth.uid()) or exists(select 1 from public.servers s where s.id=server_id and s.owner_id=(select auth.uid())));
create policy "leave or owner remove" on public.server_members for delete to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.servers s where s.id=server_id and s.owner_id=(select auth.uid())));
create policy "read member channels" on public.channels for select to authenticated using(public.is_member(server_id));
create policy "owner creates channels" on public.channels for insert to authenticated with check(exists(select 1 from public.servers s where s.id=server_id and s.owner_id=(select auth.uid())));
create policy "owner edits channels" on public.channels for update to authenticated using(exists(select 1 from public.servers s where s.id=server_id and s.owner_id=(select auth.uid()))) with check(exists(select 1 from public.servers s where s.id=server_id and s.owner_id=(select auth.uid())));
create policy "owner deletes channels" on public.channels for delete to authenticated using(exists(select 1 from public.servers s where s.id=server_id and s.owner_id=(select auth.uid())));
create policy "read channel messages" on public.messages for select to authenticated using(public.channel_member(channel_id));
create policy "send own messages" on public.messages for insert to authenticated with check(user_id=(select auth.uid()) and public.channel_member(channel_id));
create policy "delete own messages" on public.messages for delete to authenticated using(user_id=(select auth.uid()));
create policy "read reactions" on public.message_reactions for select to authenticated using(exists(select 1 from public.messages m where m.id=message_id and public.channel_member(m.channel_id)));
create policy "add own reactions" on public.message_reactions for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.messages m where m.id=message_id and public.channel_member(m.channel_id)));
create policy "remove own reactions" on public.message_reactions for delete to authenticated using(user_id=(select auth.uid()));
create policy "read own friendships" on public.friendships for select to authenticated using(requester_id=(select auth.uid()) or addressee_id=(select auth.uid()));
create policy "send friend request" on public.friendships for insert to authenticated with check(requester_id=(select auth.uid()));
create policy "read own dm participants" on public.dm_participants for select to authenticated using(user_id=(select auth.uid()));
create policy "read dm conversation" on public.dm_conversations for select to authenticated using(exists(select 1 from public.dm_participants p where p.conversation_id=id and p.user_id=(select auth.uid())));
create policy "read dm messages" on public.dm_messages for select to authenticated using(exists(select 1 from public.dm_participants p where p.conversation_id=conversation_id and p.user_id=(select auth.uid())));
create policy "send dm messages" on public.dm_messages for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.dm_participants p where p.conversation_id=conversation_id and p.user_id=(select auth.uid())));
alter publication supabase_realtime add table public.messages;